"""Run from the folder containing pyproject.toml:  python fix_sitelinks.py
Adds a fallback source of safe URLs (real internal links from Tranco homepages) used when the
Common Crawl index is down, and makes the Common Crawl step fail fast instead of waiting 5 minutes."""
from pathlib import Path

root = Path.cwd()
if not (root / "pyproject.toml").exists():
    raise SystemExit("Run this from the folder that contains pyproject.toml")
FILES = [
    ('src/abuselens/ingest/sitelinks.py', '"""Fallback source of safe URLs with realistic paths: real internal links from each sampled\nTranco site\'s own homepage (one polite GET per site).\n\nUsed when the Common Crawl index is unavailable. Pages are only parsed as text (never executed).\n"""\nfrom __future__ import annotations\n\nimport time\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\nfrom concurrent.futures import TimeoutError as FutTimeout\nfrom html.parser import HTMLParser\nfrom urllib.parse import urldefrag, urljoin, urlsplit\n\nimport pandas as pd\nimport requests\n\nfrom .. import config\n\nSKIP_EXT = (".jpg", ".jpeg", ".png", ".gif", ".svg", ".webp", ".ico", ".css", ".js", ".pdf", ".zip",\n            ".mp4", ".mp3", ".woff", ".woff2", ".xml", ".json")\n\n\nclass _Links(HTMLParser):\n    def __init__(self):\n        super().__init__()\n        self.hrefs: list[str] = []\n\n    def handle_starttag(self, tag, attrs):\n        if tag == "a":\n            for k, v in attrs:\n                if k == "href" and v:\n                    self.hrefs.append(v)\n\n\ndef _site(host: str) -> str:\n    return host[4:] if host.startswith("www.") else host\n\n\ndef extract_links(html: str, base_url: str, limit: int) -> list[str]:\n    """Same-site http(s) links that have a real path, de-duplicated, in page order."""\n    p = _Links()\n    try:\n        p.feed(html[:500_000])\n    except Exception:  # malformed HTML must never break the pipeline\n        pass\n    base_host = _site(urlsplit(base_url).hostname or "")\n    out, seen = [], set()\n    for h in p.hrefs:\n        u, _ = urldefrag(urljoin(base_url, h.strip()))\n        sp = urlsplit(u)\n        if sp.scheme not in ("http", "https") or _site(sp.hostname or "") != base_host:\n            continue\n        if sp.path in ("", "/") and not sp.query:\n            continue\n        if sp.path.lower().endswith(SKIP_EXT) or u in seen:\n            continue\n        seen.add(u)\n        out.append(u)\n        if len(out) >= limit:\n            break\n    return out\n\n\ndef _one(rank, dom: str, per_domain: int) -> list[dict]:\n    for scheme in ("https", "http"):\n        try:\n            r = requests.get(f"{scheme}://{dom}/", headers={"User-Agent": config.USER_AGENT},\n                             timeout=8, allow_redirects=True)\n        except requests.RequestException:\n            continue\n        if r.status_code == 200 and "html" in r.headers.get("content-type", "").lower():\n            return [{"url": u, "domain": dom, "tranco_rank": int(rank), "source": "sitelinks"}\n                    for u in extract_links(r.text, r.url, per_domain)]\n        return []\n    return []\n\n\ndef fetch_for_domains(domains: pd.DataFrame, per_domain: int | None = None,\n                      budget_s: float | None = None, workers: int = 16) -> pd.DataFrame:\n    per_domain = per_domain or config.CC_URLS_PER_DOMAIN\n    budget_s = budget_s or config.CC_TIME_BUDGET_S\n    start, rows, done = time.monotonic(), [], 0\n    pairs = list(zip(domains["rank"], domains["domain"], strict=True))\n    ex = ThreadPoolExecutor(max_workers=workers)\n    futs = [ex.submit(_one, rk, dm, per_domain) for rk, dm in pairs]\n    try:\n        for f in as_completed(futs, timeout=budget_s):\n            rows.extend(f.result())\n            done += 1\n            if done % 50 == 0:\n                print(f"  sitelinks: {done}/{len(pairs)} sites, {len(rows)} urls "\n                      f"({time.monotonic() - start:.0f}s)", flush=True)\n    except FutTimeout:\n        print(f"  sitelinks: time budget {budget_s}s reached; keeping {len(rows)} urls", flush=True)\n    finally:\n        ex.shutdown(wait=False, cancel_futures=True)\n    return pd.DataFrame(rows, columns=["url", "domain", "tranco_rank", "source"])\n'),
    ('src/abuselens/ingest/commoncrawl.py', '"""Common Crawl URL index: real paths for sampled legitimate domains.\n\nBare domains make trivially easy negatives. Pulling real crawled URLs for each sampled\nTranco domain gives the model negatives with realistic paths and query strings.\n"""\nfrom __future__ import annotations\n\nimport json\nimport time\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\nfrom concurrent.futures import TimeoutError as TimeoutError  # noqa: PLC0414\n\nimport pandas as pd\n\nfrom .. import config\nfrom . import http\n\n\ndef latest_index_api() -> str:\n    return http.get(config.COMMONCRAWL_COLLINFO).json()[0]["cdx-api"]\n\n\ndef parse_cdx(text: str, limit: int) -> list[str]:\n    urls = []\n    for ln in text.splitlines():\n        try:\n            rec = json.loads(ln)\n        except json.JSONDecodeError:\n            continue\n        if str(rec.get("status")) == "200" and rec.get("url", "").startswith("http"):\n            urls.append(rec["url"])\n        if len(urls) >= limit:\n            break\n    return urls\n\n\ndef available() -> bool:\n    """One quick probe so a down index costs seconds, not the whole time budget."""\n    try:\n        api = latest_index_api()\n        r = http.get(api, params={"url": "example.com/*", "output": "json", "limit": 1},\n                     retries=1, timeout=15)\n        return r.status_code == 200\n    except Exception:\n        return False\n\n\ndef _one(api: str, rank, dom: str, per_domain: int) -> list[dict]:\n    try:\n        r = http.get(api, params={"url": f"{dom}/*", "output": "json", "limit": per_domain * 4,\n                                  "filter": "=status:200"}, retries=1, timeout=15)\n    except RuntimeError:\n        return []\n    return [{"url": u, "domain": dom, "tranco_rank": int(rank), "source": "commoncrawl"}\n            for u in parse_cdx(r.text, per_domain)]\n\n\ndef fetch_for_domains(domains: pd.DataFrame, per_domain: int | None = None,\n                      budget_s: float | None = None, workers: int = 8) -> pd.DataFrame:\n    """Parallel, time-bounded lookups. Returns whatever was collected when the budget runs out."""\n    per_domain = per_domain or config.CC_URLS_PER_DOMAIN\n    budget_s = budget_s or config.CC_TIME_BUDGET_S\n    api = latest_index_api()\n    start, rows, done = time.monotonic(), [], 0\n    pairs = list(zip(domains["rank"], domains["domain"], strict=True))\n    ex = ThreadPoolExecutor(max_workers=workers)\n    futs = [ex.submit(_one, api, rk, dm, per_domain) for rk, dm in pairs]\n    try:\n        for f in as_completed(futs, timeout=budget_s):\n            rows.extend(f.result())\n            done += 1\n            if done % 25 == 0:\n                print(f"  commoncrawl: {done}/{len(pairs)} domains, {len(rows)} urls "\n                      f"({time.monotonic() - start:.0f}s)", flush=True)\n    except TimeoutError:\n        print(f"  commoncrawl: time budget {budget_s}s reached; keeping {len(rows)} urls "\n              f"from {done}/{len(pairs)} domains", flush=True)\n    finally:\n        ex.shutdown(wait=False, cancel_futures=True)\n    return pd.DataFrame(rows, columns=["url", "domain", "tranco_rank", "source"])\n'),
    ('src/abuselens/ingest/runner.py', '"""Orchestrates one daily ingest: fetch -> validate -> load, with an audit log."""\nfrom __future__ import annotations\n\nimport datetime as dt\nimport logging\n\nimport pandas as pd\n\nfrom .. import db\nfrom ..quality.checks import validate\nfrom . import commoncrawl, openphish, phishtank, sitelinks, tranco, urlhaus\n\nlog = logging.getLogger("abuselens.ingest")\n\nFEEDS = {\n    "urlhaus": (urlhaus.fetch, "raw_urlhaus"),\n    "openphish": (openphish.fetch, "raw_openphish"),\n    "phishtank": (phishtank.fetch, "raw_phishtank"),\n}\n\n\ndef _prior_counts(con, table: str, today) -> list[int]:\n    rows = con.execute(\n        f"SELECT count(*) FROM {table} WHERE snapshot_date < ? GROUP BY snapshot_date "\n        "ORDER BY snapshot_date DESC LIMIT 7", [today]).fetchall()\n    return [r[0] for r in rows]\n\n\ndef _log(con, source, today, n, status, msg=""):\n    con.execute("INSERT INTO ingest_log VALUES (?,?,?,?,?,?)",\n                [dt.datetime.now(dt.timezone.utc).replace(tzinfo=None), source, today, n, status, msg[:500]])\n\n\ndef ingest_feed(con, name: str, df: pd.DataFrame, table: str, today) -> bool:\n    df, rep = validate(name, df, prior_row_counts=_prior_counts(con, table, today))\n    if not rep.ok:\n        _log(con, name, today, 0, "rejected", "; ".join(rep.errors))\n        log.error("%s rejected: %s", name, rep.errors)\n        return False\n    n = db.load_snapshot(con, table, df, today)\n    _log(con, name, today, n, "ok", "; ".join(rep.warnings))\n    return True\n\n\ndef run(con, sources: list[str], today: dt.date | None = None) -> dict[str, bool]:\n    today = today or dt.date.today()\n    results: dict[str, bool] = {}\n    for name, (fetch, table) in FEEDS.items():\n        if name not in sources:\n            continue\n        try:\n            results[name] = ingest_feed(con, name, fetch(), table, today)\n        except Exception as e:  # one broken feed must not stop the others\n            _log(con, name, today, 0, "error", repr(e))\n            log.exception("%s failed", name)\n            results[name] = False\n\n    if "tranco" in sources:\n        try:\n            tr = tranco.fetch()\n            _, rep = validate("tranco", tr)\n            if not rep.ok:\n                _log(con, "tranco", today, 0, "rejected", "; ".join(rep.errors))\n                results["tranco"] = False\n            else:\n                # Only the sampled safe URLs are stored daily (not 1M rows/day).\n                seed = int(today.strftime("%Y%m%d"))\n                from .. import config\n                sample = tranco.sample_safe_domains(tr, config.SAFE_DOMAINS_PER_DAY, seed)\n                safe = pd.DataFrame(columns=["url", "domain", "tranco_rank", "source"])\n                if "commoncrawl" in sources:\n                    if commoncrawl.available():\n                        safe = commoncrawl.fetch_for_domains(sample)\n                    else:\n                        print("  commoncrawl index unavailable (5xx/timeout); using site links instead",\n                              flush=True)\n                if len(safe) < 50 and ("commoncrawl" in sources or "sitelinks" in sources):\n                    safe = sitelinks.fetch_for_domains(sample)\n                if safe.empty:  # fall back to bare-domain homepage URLs\n                    safe = pd.DataFrame({"url": "https://" + sample["domain"] + "/",\n                                         "domain": sample["domain"],\n                                         "tranco_rank": sample["rank"], "source": "tranco"})\n                n = db.load_snapshot(con, "raw_safe_urls", safe, today)\n                _log(con, "tranco", today, n, "ok")\n                results["tranco"] = True\n        except Exception as e:\n            _log(con, "tranco", today, 0, "error", repr(e))\n            results["tranco"] = False\n    return results\n'),
    ('src/abuselens/cli.py', '"""`abuselens` command line: ingest | marts | enrich | train | monitor | report."""\nfrom __future__ import annotations\n\nimport argparse\nimport logging\nimport sys\n\nfrom . import config, db\nfrom .ingest import runner\n\nALL_SOURCES = ["urlhaus", "openphish", "phishtank", "tranco", "commoncrawl", "sitelinks"]\n\n\ndef cmd_ingest(a):\n    con = db.connect()\n    sources = ALL_SOURCES if a.all else a.sources\n    res = runner.run(con, sources)\n    for k, ok in res.items():\n        print(f"{k:10s} {\'ok\' if ok else \'FAILED (see ingest_log)\'}")\n    return 0 if all(res.values()) else 1\n\n\ndef cmd_marts(a):\n    con = db.connect()\n    for sub in ("staging", "marts"):\n        print(sub, db.run_sql_dir(con, sub))\n    return 0\n\n\ndef cmd_enrich(a):\n    from .enrich.context import enrich_domains\n    con = db.connect()\n    hosts = [r[0] for r in con.execute("""\n        SELECT host FROM (SELECT host FROM stg_malicious_urls UNION ALL SELECT host FROM stg_safe_urls)\n        WHERE host NOT SIMILAR TO \'[0-9.]+\' AND host <> \'\'\n          AND host NOT IN (SELECT domain FROM raw_enrichment)\n        GROUP BY host ORDER BY random() LIMIT ?""", [a.max]).fetchall()]\n    df = enrich_domains(hosts, max_n=a.max)\n    con.register("_e", df)\n    con.execute("INSERT INTO raw_enrichment SELECT * FROM _e")\n    print(f"enriched {len(df)} domains")\n    return 0\n\n\ndef cmd_train(a):\n    from .models import train\n    con = db.connect()\n    db.run_sql_dir(con, "staging")\n    meta = train.train_and_promote(con)\n    m = meta["metrics"]\n    print(f"{meta[\'decision\']} | PR-AUC {m[\'pr_auc\']:.3f} ROC-AUC {m[\'roc_auc\']:.3f} "\n          f"recall {m[\'recall\']:.2%} FPR {m[\'fpr\']:.2%}")\n    return 0\n\n\ndef _monitor(con):\n    from .models import train\n    from .monitoring import drift\n    bundle, _ = train.load(config.MODEL_DIR / "champion")\n    return drift.run(con, bundle)\n\n\ndef cmd_monitor(a):\n    con = db.connect()\n    res = _monitor(con)\n    print(res["decay"].round(3).to_string(index=False))\n    for al in res["alerts"] or ["no alerts"]:\n        print("-", al)\n    return 0\n\n\ndef cmd_report(a):\n    import json\n\n    from .reporting import brief\n    con = db.connect()\n    for sub in ("staging", "marts"):\n        db.run_sql_dir(con, sub)\n    meta_path = config.MODEL_DIR / "champion" / "meta.json"\n    meta = json.loads(meta_path.read_text(encoding="utf-8")) if meta_path.exists() else None\n    try:\n        mon = _monitor(con) if meta else None\n    except Exception:\n        mon = None\n    print(brief.write(brief.build(con, meta, mon)))\n    return 0\n\n\ndef main(argv=None) -> int:\n    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(name)s %(message)s")\n    p = argparse.ArgumentParser(prog="abuselens")\n    sub = p.add_subparsers(dest="cmd", required=True)\n    s = sub.add_parser("ingest")\n    s.add_argument("--all", action="store_true")\n    s.add_argument("--sources", nargs="*", default=[], choices=ALL_SOURCES)\n    s.set_defaults(fn=cmd_ingest)\n    sub.add_parser("marts").set_defaults(fn=cmd_marts)\n    s = sub.add_parser("enrich")\n    s.add_argument("--max", type=int, default=200)\n    s.set_defaults(fn=cmd_enrich)\n    sub.add_parser("train").set_defaults(fn=cmd_train)\n    sub.add_parser("monitor").set_defaults(fn=cmd_monitor)\n    sub.add_parser("report").set_defaults(fn=cmd_report)\n    a = p.parse_args(argv)\n    return a.fn(a)\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'),
]
for rel, text in FILES:
    (root / rel).write_text(text, encoding="utf-8", newline="")
    print("patched", rel)
